package com.praffull.programs;

public class RelationalOperators {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int x,y;
		x=13;
		y=9;
		System.out.println(x==y);
		System.out.println(x>y);
		// >=, <, <=
		System.out.println(x!=y);
		// result is always boolean (true/false)
	}

}
